import sys,os;sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)));from viet_chung import xuat
# Thủy mặc tập 5: Hàm Tử, Chương Dương, Tây Kết 1285 (mã tm5), bản 3: mỗi trận đẩy cao hơn trận trước
S=[
(1,"Có một vị tướng bị giặc bắt sống, được hứa cho làm vương nếu chịu hàng, và ông chỉ đáp đúng một câu."),
(1,"Ông nói thà làm quỷ nước Nam, chứ không thèm làm vương đất Bắc. Nói xong câu ấy, ông bị giết ngay."),
(1,"Người tướng ấy là Trần Bình Trọng. Khi ông chết, quân nhà Nguyên đã chiếm kinh thành và triều đình phải bỏ chạy về phía nam."),
(1,"Vậy mà chỉ nửa năm sau, chính quân nhà Nguyên phải tháo chạy, sau ba trận đánh trên ba bến sông. Ba trận ấy đã diễn ra thế nào?"),
(2,"Mọi chuyện bắt đầu từ một lời đòi. Năm một nghìn hai trăm tám mươi tư, nhà Nguyên đòi mượn đường qua Đại Việt để đánh nước Chiêm Thành ở phía nam."),
(2,"Cho mượn đường thì chẳng khác gì mở cửa cho giặc vào nhà, nên nhà Trần từ chối. Nhà Nguyên liền lấy cớ ấy để đem quân sang đánh."),
(2,"Hoàng đế Hốt Tất Liệt sai con trai là Thoát Hoan dẫn đại quân xuống biên giới phía bắc. Phía nam, tướng Toa Đô của nhà Nguyên đóng sẵn ở Chiêm Thành."),
(2,"Chiến tranh đã tới trước cửa. Thượng hoàng Trần Thánh Tông bèn mời các bô lão về điện Diên Hồng hỏi nên hòa hay nên đánh, các cụ đều đáp: đánh."),
(2,"Còn trong quân, binh lính tự thích lên cánh tay hai chữ Sát Thát, nghĩa là giết giặc Mông Cổ. Cuối năm ấy, quân của Thoát Hoan tràn qua biên giới."),
(3,"Trần Quốc Tuấn, tức Hưng Đạo Đại Vương, đem quân chặn ở biên giới nhưng không giữ nổi. Ông phải lui về Vạn Kiếp, rồi lui tiếp."),
(3,"Thế là kinh thành Thăng Long bị bỏ trống. Đầu năm sau, quân nhà Nguyên vào thành, triều đình lánh dần xuống phía nam."),
(3,"Cùng lúc ấy, Toa Đô từ phía nam đánh ra Nghệ An, Thanh Hóa. Quân giặc đang kẹp nước ta từ cả hai đầu."),
(3,"Ở phía bắc, Trần Bình Trọng chặn giặc ở bãi Đà Mạc, bên sông Thiên Mạc. Ông thua trận, bị bắt, và chết vì câu trả lời ở đầu câu chuyện."),
(3,"Tin xấu chưa dừng ở đó. Em trai Thượng hoàng là Trần Ích Tắc dẫn cả nhà sang hàng giặc, rồi tướng Trần Kiện cũng ra hàng Toa Đô."),
(3,"Rồi hai vua Trần phải đi thuyền lánh ra vùng biển Thanh Hóa. Đó là lúc nhà Trần xuống thấp nhất trong cả cuộc chiến."),
(4,"Nhưng quân nhà Nguyên chiếm được thành mà không bắt được vua, cũng không lấy được bao nhiêu lương thực."),
(4,"Rồi mùa hè tới. Trời nóng, mưa nhiều, quân lính nhà Nguyên ốm dần, mà đất đai chung quanh thì không chỗ nào yên."),
(4,"Trong lúc ấy, Toa Đô kéo quân từ phía nam lên để hợp với Thoát Hoan. Hai cánh quân giặc đang tiến lại gần nhau dọc sông Hồng."),
(4,"Giặc yếu dần mà lại dồn về sông Hồng. Đó là lúc nhà Trần phản công, ngay trên các bến sông mà quân thuyền Đại Việt quen thuộc nhất."),
(5,"Bến sông đầu tiên là Hàm Tử. Tháng Tư, Trần Nhật Duật đem quân thuyền tới đó, chặn đánh cánh quân của Toa Đô."),
(5,"Trong đoàn quân của ông có một toán người nhà Tống chạy sang nương nhờ, do Triệu Trung cầm đầu. Họ ra trận vẫn mặc nguyên áo quần kiểu Tống."),
(5,"Quân giặc nhìn sang thì hoảng. Họ tưởng nhà Tống đã sang đánh giúp Đại Việt, hàng ngũ rối loạn rồi vỡ chạy."),
(5,"Trận đầu đã thắng. Nhưng kinh thành vẫn trong tay Thoát Hoan, và Toa Đô vẫn đang trên đường lên."),
(6,"Vì thế, việc lấy lại kinh thành giao cho Thượng tướng Trần Quang Khải, người đứng đầu các võ quan. Ông nhắm vào bến Chương Dương, ngay cửa ngõ kinh thành."),
(6,"Đi cùng ông có Trần Quốc Toản, một tướng trẻ chưa tới hai mươi tuổi, mang lá cờ tự làm đề sáu chữ: phá cường địch, báo hoàng ân."),
(6,"Ở Chương Dương, bến sông thứ hai, quân Đại Việt đánh tan giặc, rồi không dừng lại mà đuổi thẳng tới chân thành Thăng Long."),
(6,"Thế là quân nhà Nguyên trong thành đánh không lại, phải bỏ kinh thành rút qua sông. Chỉ vài tháng sau ngày bỏ trống, Thăng Long đã về tay nhà Trần."),
(7,"Nhưng trận lớn nhất vẫn còn ở phía trước. Toa Đô vẫn còn nguyên đạo quân, đóng ở Tây Kết bên sông Hồng."),
(7,"Đạo quân ấy đã đánh ở Chiêm Thành hai năm, rồi đánh dọc từ Nghệ An ra. Thua một trận ở Hàm Tử, họ vẫn còn rất đông và quen trận mạc."),
(7,"Vì vậy, lần này chính hai vua Trần tự đem quân tới. Tháng Năm, quân Đại Việt vây đánh doanh trại của Toa Đô ở Tây Kết."),
(7,"Rồi doanh trại giặc tan vỡ. Toa Đô bị chém đầu ngay trong trận, còn tướng Ô Mã Nhi chạy thoát ra biển."),
(7,"Theo sử cũ, khi đầu Toa Đô được đem về, vua Trần Nhân Tông than rằng làm bề tôi nên như người này, rồi cởi áo mình sai đem liệm."),
(7,"Đó là bến sông thứ ba. Gọng kìm phía nam đã gãy, và Thoát Hoan giờ chỉ còn một mình giữa đất Đại Việt."),
(8,"Không còn đường nào khác, Thoát Hoan tháo chạy về phương bắc. Con đường ngắn nhất lại đi qua Vạn Kiếp, nơi Trần Quốc Tuấn đã chờ sẵn."),
(8,"Phục binh đổ ra đánh vào đoàn quân đang chạy. Tướng Lý Hằng che chắn phía sau thì trúng tên độc mà chết."),
(8,"Còn Thoát Hoan, con trai hoàng đế nhà Nguyên, theo lời kể trong sử cũ, phải chui vào một cái ống đồng cho quân lính khiêng chạy về nước."),
(9,"Tháng Sáu, hai vua trở về kinh thành Thăng Long. Từ lúc giặc tràn sang đến khi chúng chạy hết, chỉ khoảng nửa năm."),
(9,"Còn Trần Bình Trọng thì không được thấy ngày ấy. Vua thương xót, phong tước vương cho ông sau khi mất."),
(9,"Một vị tướng chọn làm quỷ nước Nam, rồi sau ba bến sông, chính quân giặc phải rời đất Nam. Cảm ơn bạn đã lắng nghe câu chuyện này."),
]
xuat(S,'tm5',180001)
